import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
const read=p=>readFileSync(p,'utf8'),j=p=>JSON.parse(read(p));
const dir='content/uc3m/tema-20/';
const manual=read(dir+'manual.md'),sources=read(dir+'fuentes.md');
const matrix=j(dir+'matriz.json'),bank=j(dir+'preguntas.json');
const cotejo=read(dir+'cotejo-integral-2026-11-04.md');
const acta=read('content/uc3m/CIERRE_DOCUMENTAL_T20_20261106.md');
const extras=j('data/uc3m-repaso-presupuesto-contratacion-t18-t20-20261106.json').preguntas.filter(q=>q.tema===20);
const guide=read('content/uc3m/GUIA_EXAMEN_2026.md');
const status=read('AUDITORIA_CONTINUA.md');
assert.equal(matrix.estado,'EN_REVISION_USUARIO');
assert.equal(matrix.cobertura.length,10);
assert.equal(bank.preguntas.length,12);
const headings=[...manual.matchAll(/^## (\d+)\. /gm)].map(m=>+m[1]).filter(n=>n<=29);
assert.deepEqual([...new Set(headings)],Array.from({length:29},(_,i)=>i+1));
assert.ok(manual.includes('CIERRE_DOCUMENTAL_T20_20261106.md'));
assert.ok(sources.includes('CIERRE_DOCUMENTAL_T20_20261106.md'));
assert.ok(manual.includes('art. 118.5')&&manual.includes('art. 159'));
assert.ok(acta.includes('68 alternativas')&&acta.includes('140.000'));
assert.ok(sources.includes('BOE-A-2017-12902'));
assert.ok(sources.includes('BOE-A-2025-26605'));
const ids=new Set();
for(const q of bank.preguntas){
 assert.ok(q.id&&!ids.has(q.id));ids.add(q.id);
 assert.equal(q.opciones.length,4);
 assert.equal(new Set(q.opciones).size,4);
 assert.ok(q.opciones.every(s=>typeof s==='string'&&s.trim()));
 assert.ok(Number.isInteger(q.correcta)&&q.correcta>=0&&q.correcta<=3);
 assert.equal(q.respuestaLiteral,q.opciones[q.correcta]);
 assert.ok(q.justificacion&&q.trampa&&q.referencia);
 assert.ok(q.referencia.includes('https://'),'Falta referencia oficial '+q.id);
 assert.ok(cotejo.includes('### '+q.id+' — '+q.pregunta),'Sin cotejo '+q.id);
}
assert.equal(extras.length,5);
const arts=['159','159','159','153','118'];
for(const [i,q] of extras.entries()){
 assert.ok(q.id&&!ids.has(q.id));ids.add(q.id);
 assert.equal(q.opciones.length,4);
 assert.equal(new Set(q.opciones).size,4);
 assert.equal(q.respuestaLiteral,q.opciones[q.correcta]);
 assert.ok(q.justificacion&&q.trampaExamen&&q.fundamento&&q.referencia);
 assert.ok(q.referencia.includes('LCSP art. ')&&q.referencia.includes('BOE-A-2017-12902#a'+arts[i]),'Sin articulo preciso '+q.id);
}
const c=matrix.cierreDocumentalT20_20261106;
assert.equal(c?.resultado,'CIERRE_DOCUMENTAL_REGISTRADO_CON_RESERVAS');
assert.equal(c?.bloquesMatriz,10);
assert.equal(c?.preguntasOriginales,12);
assert.equal(c?.alternativasOriginales,48);
assert.equal(c?.preguntasComplementarias,5);
assert.equal(c?.alternativasComplementarias,20);
assert.equal(c?.preguntasTotal,17);
assert.equal(c?.alternativasTotal,68);
assert.equal(c?.refsPrecisadas,17);
assert.equal(c?.aprobacionUsuario,false);
assert.equal(c?.certificacionIntegral,false);
assert.equal(c?.ciPendiente,true);
assert.equal(c?.navegadorE2E,false);
assert.ok(guide.includes('CIERRE_DOCUMENTAL_T20_20261106.md'));
assert.ok(status.includes('CIERRE_DOCUMENTAL_T20_20261106.md'));
assert.equal(ids.size,17);
console.log('UC3M T20: 10 BLOQUES, 17 PREGUNTAS, 68 ALTERNATIVAS, UMBRALES 2026 Y RESERVAS');
